<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class MunicipalitySeeder extends Seeder
{
    public function run(): void
    {
        $encoded = '';
        $json = gzdecode(base64_decode($encoded, true));

        foreach (json_decode($json, true, 512, JSON_THROW_ON_ERROR)['features'] as $feature) {
            $attributes = $feature['attributes'];

            DB::table('municipalities')->updateOrInsert(
                ['code' => $attributes['MPIO_CDPMP']],
                [
                    'name' => $attributes['MPIO_CNMBRE'],
                    'department' => $attributes['DPTO_CNMBRE'],
                    'updated_at' => now(),
                    'created_at' => now(),
                ],
            );
        }
    }
}
